import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import './Ideas.css';
import { getUserId, getIdeas } from "../data/tripInfo";
import IdeaCard from '../components/IdeaCard';
import TripBanner from '../components/TripBanner';
import { FiFilter } from 'react-icons/fi'; 

function Ideas() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [allIdeas, setAllIdeas] = useState([]);
  const [filteredIdeas, setFilteredIdeas] = useState([]);
  const [searchQuery, setSearchQuery] = useState(''); 
  const [selectedTag, setSelectedTag] = useState('');
  const filterButtonRef = useRef(null);
  const [showDropdown, setShowDropdown] = useState(false);

  const toggleDropdown = () => {
    setShowDropdown(prev => !prev);
  };

  const handleTagSelect = (tag) => {
    setSelectedTag(tag);
    setShowDropdown(false); // Close dropdown on selection
  };

  useEffect(() => {
    if (showDropdown) {
      const buttonRect = document.querySelector('.filter-overlay-btn').getBoundingClientRect();
      const dropdown = document.querySelector('.custom-dropdown');

      if (dropdown) {
        dropdown.style.top = `${buttonRect.bottom + window.scrollY - 10}px`;
        dropdown.style.left = `${buttonRect.left + window.scrollX - 80}px`;
      }
    }
  }, [showDropdown]);

  useEffect(() => {
    async function fetchIdeas() {
      const fetchedIdeas = await getIdeas(id);
      const processedIdeas = fetchedIdeas.map(idea => {
        const yesVotes = idea.votes?.yes?.length || 0;
        const noVotes = idea.votes?.no?.length || 0;
        const totalVotes = yesVotes + noVotes;
        const acceptancePercentage = totalVotes > 0 ? (yesVotes / totalVotes) * 100 : 0;
        return {
          ...idea,
          acceptancePercentage: acceptancePercentage.toFixed(2),
          dateObj: idea.date?.toDate ? idea.date.toDate() : new Date(idea.date),
        };
      });

      processedIdeas.sort((a, b) => {
        const diff = parseFloat(b.acceptancePercentage) - parseFloat(a.acceptancePercentage);
        if (diff !== 0) return diff;
        return a.dateObj - b.dateObj;
      });
      setAllIdeas(processedIdeas);
    }

    fetchIdeas();
  }, [id]);

  useEffect(() => {
    const userId = getUserId();

    const filtered = allIdeas.filter((idea) => {
      const matchesSearch = idea.name.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesTag = selectedTag ? idea.tags?.includes(selectedTag) : true;
      return !idea.archived && matchesSearch && matchesTag;
    });

    setFilteredIdeas(filtered);
  }, [allIdeas, searchQuery, selectedTag]);

  const goToNewIdea = () => {
    navigate(`/trip/${id}/ideas/new`);
  };

  const allTags = [...new Set(allIdeas.flatMap(idea => idea.tags || []))];

  return (
    <div className="ideas-page">
      <div className='fixed-content'>
        <TripBanner id={id} />
        <div className="ideas-header">
          <h2 className="ideas-title">Ideas</h2>
          <button className="add-idea-button" onClick={goToNewIdea}>＋</button>
        </div>

        <div className="search-bar">
          <input
            type="text"
            placeholder="Search"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          <div className="tag-filter">
            <button className="filter-overlay-btn" onClick={toggleDropdown}>
              <FiFilter color="#9FA7AF" />
            </button>

            {showDropdown && (
              <ul className="custom-dropdown">
                <li 
                  className={selectedTag === "" ? "selected" : ""}
                  onClick={() => handleTagSelect("")}
                >
                  None
                </li>
                {allTags.map((tag, idx) => (
                  <li 
                    key={idx} 
                    className={selectedTag === tag ? "selected" : ""}
                    onClick={() => handleTagSelect(tag)}
                  >
                    {tag}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>

      <div className="scrollable-content">
        <div className="idea-list">
          {filteredIdeas.length === 0 ? (
            <p className="no-ideas">No ideas found.</p>
          ) : (
            filteredIdeas.map((idea, i) => (
              <IdeaCard idea={idea} key={i} />
            ))
          )}
        </div>
      </div>
    </div>
  );
}

export default Ideas;
